package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public class ClaudeReviewTest {
 @Test public void sampleRootsAndMovieTitlesRemainUsable()throws Exception{for(String root:List.of("/video/Samples","/video")){String folder=root+"/Samples",file=folder+"/S01E01.mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(file);MediaDeletion inv=new MediaDeletion(List.of(folder),List.of(root),false,fs,List.of());assertTrue(inv.plan(null).files.contains(file));}String file="/video/Sample Size (2019)/Sample Size (2019).mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(file);assertTrue(new MediaDeletion(List.of(file),List.of("/video"),true,fs,List.of()).plan(null).files.contains(file));}
 @Test public void onlySampleComponentsBelowCardRootCount()throws Exception{String root="/video/Show";assertTrue(MediaDeletion.sample(root+"/Sample/x.mkv",List.of(root)));assertTrue(MediaDeletion.sample(root+"/Samples/x.mkv",List.of(root)));assertTrue(MediaDeletion.sample(root+"/Show.sample.mkv",List.of(root)));assertFalse(MediaDeletion.sample(root+"/Sample Size (2019).mkv",List.of(root)));String episode=root+"/S01E01.mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(episode,root+"/Samples/S02E01.mkv");assertEquals(Set.of(1),new MediaDeletion(List.of(root),List.of("/video"),false,fs,List.of()).seasons);}
 @Test public void trailingPhysicalSlashDoesNotWeakenContainment()throws Exception{String p="/video/Film/Film.mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(p);for(NasClient.Entry e:fs.rows.values())e.realPath+="/";MediaDeletion inv=new MediaDeletion(List.of(p),List.of("/video"),true,fs,List.of());assertTrue(inv.plan(null).files.contains(p));fs.rows.get(p).realPath="/volume1/Private/Film.mkv/";assertThrows(IOException.class,()->new MediaDeletion(List.of(p),List.of("/video"),true,fs,List.of()));}
 @Test public void publicHttpWarnsOnceButPrivateHttpRemainsAllowed(){NasClient.Credentials c=new NasClient.Credentials("http://nyilvanos.pelda.hu:5000","http://192.168.1.10:5000","u","p","");List<String> pending=HttpConsent.pending(c,k->false);assertEquals(List.of("http://nyilvanos.pelda.hu:5000"),pending);assertTrue(HttpConsent.pending(c,pending::contains).isEmpty());assertEquals("http://nyilvanos.pelda.hu:5000",NasClient.normalizeAddress(c.address));assertFalse(NasClient.sslMessage(new javax.net.ssl.SSLException("plaintext")).contains("http://"));}
 @Test public void parallelStreamsRenewOnlyOneSession()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient c=f.client();f.streamExpiry=true;f.expiredPair=new CountDownLatch(2);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<byte[]> a=pool.submit(()->c.readFile("/video/a.mkv",10)),b=pool.submit(()->c.readFile("/video/b.mkv",10));assertArrayEquals(new byte[]{1,2,3},a.get(6,TimeUnit.SECONDS));assertArrayEquals(new byte[]{1,2,3},b.get(6,TimeUnit.SECONDS));assertEquals(2,f.logins.get());}finally{pool.shutdownNow();}}}
 static byte[] event(String id,long generation)throws Exception{return new JSONObject().put("format_version",1).put("event_id",id).put("relative_path","movie.mkv").put("media_type","movie").put("tmdb_id",10).put("title","Fixture").put("deleted",false).put("generation",generation).put("created_ns",1).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test public void pairingReadDoesNotHoldClientMonitorAndIsCached()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){String id="a".repeat(32);f.pairingFiles.put(id+".json",event(id,7));NasClient c=f.client();f.slowPairingRead=true;ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> save=pool.submit(()->{c.savePairing("/video","/video/movie.mkv",true,new JSONObject().put("id",11));return null;});assertTrue(f.discoveryEntered.await(3,TimeUnit.SECONDS));assertEquals(0,pool.submit(()->c.call("SYNO.FileStation.List","list",Map.of()).getInt("total")).get(2,TimeUnit.SECONDS).intValue());assertFalse(save.isDone());f.slowPairingRead=false;f.release.countDown();save.get(5,TimeUnit.SECONDS);int reads=f.pairingReads.get();c.savePairing("/video","/video/movie.mkv",true,new JSONObject().put("id",12));assertEquals(reads+2,f.pairingReads.get());assertEquals(3,f.pairingFiles.size());long latest=0;for(byte[] bytes:f.pairingFiles.values())latest=Math.max(latest,new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getLong("generation"));assertEquals(9,latest);}finally{f.release.countDown();pool.shutdownNow();}}}
 @Test public void deletionRejectionAndUncertainWriteAreDifferent()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient c=f.client();f.rejectCode=105;IOException rejected=assertThrows(IOException.class,()->c.deleteMediaPaths(List.of("/video/a.mkv")));assertTrue(rejected.getMessage().contains("nem indult el"));assertFalse(rejected.getMessage().contains("nem igazolható"));f.rejectCode=0;f.disconnectDelete=true;IOException unknown=assertThrows(IOException.class,()->c.deleteMediaPaths(List.of("/video/a.mkv")));assertTrue(unknown.getMessage().contains("nem igazolható"));assertEquals(2,f.mediaDeletes.get());}}
 @Test public void invalidDeleteAndInterruptedDeleteNeverWrite()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient c=f.client();assertThrows(IOException.class,()->c.deleteMediaPaths(List.of("/video")));Thread.currentThread().interrupt();try{assertThrows(InterruptedException.class,()->c.deleteMediaPaths(List.of("/video/a.mkv")));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}assertEquals(0,f.mediaDeletes.get());}}
 @Test public void executeStopsWhenInventoryChangesAndOnInterruption()throws Exception{String p="/video/Film/Film.mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(p);MediaDeletion inv=new MediaDeletion(List.of(p),List.of("/video"),true,fs,List.of());MediaDeletion.Plan plan=inv.plan(null);fs.rows.get(p).modified++;assertThrows(IOException.class,()->inv.execute(plan,fs));assertTrue(fs.deletes.isEmpty());fs.rows.get(p).modified--;Thread.currentThread().interrupt();try{assertThrows(InterruptedException.class,()->inv.execute(plan,fs));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}assertTrue(fs.deletes.isEmpty());}
 @Test public void executePartialBatchFailureIsNeverReplayed()throws Exception{String root="/video/Show";String[] paths=new String[130];for(int n=0;n<paths.length;n++)paths[n]=root+"/S01E"+String.format(java.util.Locale.ROOT,"%03d",n+1)+".mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(paths);MediaDeletion inv=new MediaDeletion(List.of(root),List.of("/video"),false,fs,List.of());AtomicInteger calls=new AtomicInteger();assertThrows(IOException.class,()->inv.execute(inv.plan(null),batch->{if(calls.incrementAndGet()==2)throw new IOException("fixture partial");fs.paths(batch);}));assertEquals(2,calls.get());assertEquals(64,fs.deletes.get(0).size());assertEquals(66,fs.rows.values().stream().filter(e->!e.directory).count());}
 @Test public void streamCapabilityUsesOneImmutableSnapshot(){StreamIdentity old=new StreamIdentity("/old.mkv","old"),next=new StreamIdentity("/next.mkv","next");AtomicReference<StreamIdentity> active=new AtomicReference<>(old);StreamIdentity inFlight=active.get();active.set(next);assertEquals("old",inFlight.token);assertEquals("/old.mkv",inFlight.path);assertEquals("next",active.get().token);}
 @Test public void rejectedScanDispatchRunsCleanup(){ExecutorService stopped=Executors.newSingleThreadExecutor();stopped.shutdown();AtomicInteger cleaned=new AtomicInteger();assertNull(ScanSubmission.submit(stopped,()->fail("must not run"),cleaned::incrementAndGet));assertEquals(1,cleaned.get());}
 @Test public void uploadAndStreamShareOneSessionRenewal()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient c=f.client();f.streamExpiry=true;f.expiredCode=106;f.expiredPair=new CountDownLatch(2);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> upload=pool.submit(()->{c.savePairing("/video","/video/movie.mkv",true,new JSONObject().put("id",11));return null;});Future<byte[]> stream=pool.submit(()->c.readFile("/video/a.mkv",10));upload.get(7,TimeUnit.SECONDS);assertArrayEquals(new byte[]{1,2,3},stream.get(7,TimeUnit.SECONDS));assertEquals(2,f.logins.get());assertEquals(1,f.pairingFiles.size());}finally{pool.shutdownNow();}}}
 @Test public void replacementClientPreservesUncertainDeletionResult()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient root=f.client(),next=f.client();int generation=root.suspendConnection();assertTrue(root.installConnection(generation,next));f.disconnectDelete=true;IOException error=assertThrows(IOException.class,()->root.deleteMediaPaths(List.of("/video/a.mkv")));assertTrue(error.getMessage().contains("nem igazolható"));assertFalse(error.getMessage().contains("nem indult el"));assertEquals(1,f.mediaDeletes.get());}}
}
